BEGIN; SET LOCAL timezone='UTC'; SET LOCAL search_path=public,extensions,pg_temp;
DO $$ BEGIN IF session_user<>'fixture_bootstrap' OR current_database() !~ '^qual_spin_expiry_[0-9a-f]{32}$' OR inet_server_addr() IS NOT NULL OR current_setting('listen_addresses')<>'' THEN RAISE EXCEPTION 'ARCHIVE_PROVIDER_AUTHORITY_ISOLATION_REQUIRED'; END IF; END $$;
ALTER TABLE public.chip_ledger OWNER TO "postgres";
ALTER TABLE public.chip_ledger ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.chip_ledger NO FORCE ROW LEVEL SECURITY;
DO $$ DECLARE r record; BEGIN FOR r IN SELECT DISTINCT CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(a.grantee)) END role_name FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE c.oid='public.chip_ledger'::regclass LOOP EXECUTE 'REVOKE ALL ON public.chip_ledger FROM '||r.role_name; END LOOP; END $$;
