SET LOCAL ROLE "postgres";
GRANT EXECUTE ON FUNCTION public.is_club_admin(uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION public.is_club_admin(uuid) TO "service_role";
GRANT EXECUTE ON FUNCTION public.is_club_admin(uuid) TO "authenticated";
RESET ROLE;
CREATE OR REPLACE FUNCTION public.is_club_member(p_club_id uuid, p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM club_members
        WHERE club_id = p_club_id
        AND user_id = p_user_id
        AND status = 'active'
    );
END;
$function$;
